1	import { Box, Stack, Typography } from '@mui/material'
2	import type { ConfigEntry, ConfigKey, ConfigValues } from '../../services/config/config_service'
3	import { ConfigValueEditor } from './config_value_editor'
4	
5	const CONFIG_SECTION_SCROLL_MARGIN_TOP = 3
6	
7	interface ConfigSectionLayoutProps {
8	    disabled?: boolean
9	    draft: ConfigValues
10	    entries: ConfigEntry[]
11	    id: string
12	    label: string
13	    onChange: (key: ConfigKey, value: unknown) => void
14	    onValidityChange: (key: ConfigKey, valid: boolean) => void
15	}
16	
17	export function ConfigSectionLayout(props: ConfigSectionLayoutProps) {
18	    const { disabled = false, draft, entries, id, label, onChange, onValidityChange } = props
19	    const headingId = `${id}-config-heading`
20	
21	    return (
22	        <Box
23	            aria-labelledby={headingId}
24	            component="section"
25	            id={id}
26	            sx={{ scrollMarginTop: CONFIG_SECTION_SCROLL_MARGIN_TOP }}
27	        >
28	            <Stack spacing={3}>
29	                <Typography component="h3" id={headingId} variant="h6">
30	                    {label}
31	                </Typography>
32	                {entries.map((entry) => (
33	                    <ConfigValueEditor
34	                        disabled={disabled}
35	                        entry={entry}
36	                        key={entry.key}
37	                        onChange={onChange}
38	                        onValidityChange={onValidityChange}
39	                        value={draft[entry.key]}
40	                        values={draft}
41	                    />
42	                ))}
43	            </Stack>
44	        </Box>
45	    )
46	}
